#include "binding_metadata.hpp"
#include "rgb_dataset_internal.hpp"
#include <imagejxx/color_stack_command.hpp>
namespace py=pybind11;
using namespace imagejxx;
ExecutionControl axis_range_python_control(std::shared_ptr<CancellationToken>,py::object,py::object);
namespace {
std::size_t size_arg(py::handle v){if(PyBool_Check(v.ptr()) || py::isinstance(v,py::module_::import("numpy").attr("bool_")) || !PyIndex_Check(v.ptr()))throw py::type_error("Color stack byte limit requires an integer");auto n=py::reinterpret_steal<py::object>(PyNumber_Index(v.ptr()));if(!n)throw py::error_already_set();auto size=PyLong_AsSize_t(n.ptr());if(PyErr_Occurred())throw py::error_already_set();return size;}
bool flag(py::handle v){if(!PyBool_Check(v.ptr()))throw py::type_error("Color stack flags require bool");return v.ptr()==Py_True;}
ColorStackRequest request(ColorStackAction a,const std::string &space,ColorStackLayoutPolicy l,OutputDestination d,py::handle inverse,py::handle reset,py::handle drop,py::handle cap){
  ColorStackRequest r;r.action=a;r.layout=l;r.destination=d;r.invert_rgb=flag(inverse);r.allow_calibration_reset=flag(reset);r.allow_nonxy_annotation_drop=flag(drop);r.max_working_bytes=size_arg(cap);
  if(space=="rgb")r.space=ColorComponentSpace::RGB;else if(space=="hsb8")r.space=ColorComponentSpace::HSB8;else if(space=="hsb32")r.space=ColorComponentSpace::HSB32;else throw py::value_error("Color stack space must be rgb, hsb8 or hsb32");return r;
}
}
void bind_color_stack(py::module_ &m){
  py::enum_<ColorStackAction>(m,"ColorStackAction").value("SPLIT",ColorStackAction::Split).value("MERGE",ColorStackAction::Merge).value("FLATTEN_RGB",ColorStackAction::FlattenRgb);
  py::enum_<ColorStackLayoutPolicy>(m,"ColorStackLayoutPolicy").value("PRESERVE_AXES",ColorStackLayoutPolicy::PreserveAxes).value("IMAGEJ_LEGACY",ColorStackLayoutPolicy::ImageJLegacy);
  py::class_<ColorStackLayout>(m,"ColorStackLayout").def_property_readonly("shape",[](const ColorStackLayout &l){return l.shape.dimensions();}).def_property_readonly("pixel_type",[](const ColorStackLayout &l){return l.pixel_type==PixelType::Float32?"float32":"uint8";}).def_readonly("calibration",&ColorStackLayout::calibration).def_readonly("calibration_reset",&ColorStackLayout::calibration_reset).def_readonly("output_bytes",&ColorStackLayout::output_bytes).def_readonly("working_bytes",&ColorStackLayout::working_bytes);
  py::class_<ResolvedColorStackCommand>(m,"ResolvedColorStackCommand").def_property_readonly("source",[](const ResolvedColorStackCommand &c){return c.source();}).def_property_readonly("layout",[](const ResolvedColorStackCommand &c){return c.layout();}).def("record",[](const ResolvedColorStackCommand &c){return bindings::metadata_python(c.record());});
  m.def("resolve_color_stack_command",[](DocumentSnapshot s,ColorStackAction a,const std::string &space,ColorStackLayoutPolicy l,OutputDestination d,py::handle inverse,py::handle reset,py::handle drop,py::handle cap,py::object rendering){auto r=request(a,space,l,d,inverse,reset,drop,cap);std::optional<RgbDatasetRequest> options;if(!rendering.is_none())options=detail::rgb_dataset_request_from_record(bindings::metadata_object_value(rendering));py::gil_scoped_release release;return resolve_color_stack_command(s,r,options);},py::arg("source"),py::kw_only(),py::arg("action")=ColorStackAction::Split,py::arg("space")="rgb",py::arg("layout")=ColorStackLayoutPolicy::PreserveAxes,py::arg("destination")=OutputDestination::NewDocument,py::arg("invert_rgb")=false,py::arg("allow_calibration_reset")=false,py::arg("allow_nonxy_annotation_drop")=false,py::arg("max_working_bytes")=512ULL*1024*1024,py::arg("rendering_record")=py::none());
  m.def("validate_color_stack_command_record",[](py::dict r){auto v=bindings::metadata_object_value(r);py::gil_scoped_release release;validate_color_stack_command_record(v);});
  m.def("color_stack_command_from_record",[](DocumentSnapshot s,py::dict r){auto v=bindings::metadata_object_value(r);py::gil_scoped_release release;return color_stack_command_from_record(s,v);});
  m.def("rebind_color_stack_command",[](DocumentSnapshot s,py::dict old,ColorStackAction a,const std::string &space,ColorStackLayoutPolicy l,OutputDestination d,py::handle inverse,py::handle reset,py::handle drop,py::handle cap){auto v=bindings::metadata_object_value(old);auto r=request(a,space,l,d,inverse,reset,drop,cap);py::gil_scoped_release release;return rebind_color_stack_command(s,v,r);},py::arg("source"),py::arg("record"),py::kw_only(),py::arg("action")=ColorStackAction::Split,py::arg("space")="rgb",py::arg("layout")=ColorStackLayoutPolicy::PreserveAxes,py::arg("destination")=OutputDestination::NewDocument,py::arg("invert_rgb")=false,py::arg("allow_calibration_reset")=false,py::arg("allow_nonxy_annotation_drop")=false,py::arg("max_working_bytes")=512ULL*1024*1024);
  m.def("prepare_color_stack",[](ResolvedColorStackCommand c,std::shared_ptr<CancellationToken> token,py::object progress,py::object checkpoint,py::handle cap){auto bytes=size_arg(cap);auto control=axis_range_python_control(std::move(token),std::move(progress),std::move(checkpoint));py::gil_scoped_release release;return prepare_color_stack(c,control,bytes);},py::arg("command"),py::kw_only(),py::arg("cancellation")=py::none(),py::arg("progress")=py::none(),py::arg("checkpoint")=py::none(),py::arg("execution_max_working_bytes")=std::numeric_limits<std::size_t>::max());
}
